initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response containing:
        Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/AlreadyExists' and
        Response body containing 'title' element and
        Response Status Code set to 409
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions'
        method set to 'POST'
        Create Context Source Registration Subscription with filename set to '${subscription_payload}', accept set to '${EMPTY}', and content-type set to 'application/ld+json'
}
